import socket, concurrent.futures as cf

def probe(ip):
    for p in (80, 8080, 8081, 8000, 443, 5000, 9000, 3000):
        s = socket.socket(); s.settimeout(0.4)
        try:
            s.connect((ip, p))
            s.close()
            return (ip, p)
        except Exception:
            pass
        finally:
            s.close()
    return None

ips = [f'172.29.0.{i}' for i in range(1, 31)] + [f'172.29.{j}.{i}' for j in (1,2) for i in range(1, 11)]
with cf.ThreadPoolExecutor(64) as ex:
    for r in ex.map(probe, ips):
        if r: print('OPEN', r)
EOF"}

